import{B as e,Q as t,s as n,z as r}from"./chunks/framework.3ZETo7pw.js";var i=JSON.parse(`{"title":"GeminiService","description":"","frontmatter":{},"headers":[],"relativePath":"backend/services/gemini-service.md","filePath":"backend/services/gemini-service.md"}`),a={name:`backend/services/gemini-service.md`};function o(n,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[e('<h1 id="geminiservice" tabindex="-1">GeminiService <a class="header-anchor" href="#geminiservice" aria-label="Permalink to &quot;GeminiService&quot;">​</a></h1><p><code>app/Services/GeminiService.php</code> is the most critical component in the TechyNews repository. It orchestrates all calls to Google Gemini 2.0 (and fallback OpenRouter models) for content synthesis.</p><h2 id="core-responsibilities" tabindex="-1">Core Responsibilities <a class="header-anchor" href="#core-responsibilities" aria-label="Permalink to &quot;Core Responsibilities&quot;">​</a></h2><h3 id="_1-generateideas-array-scoutedarticles" tabindex="-1">1. <code>generateIdeas(array $scoutedArticles)</code> <a class="header-anchor" href="#_1-generateideas-array-scoutedarticles" aria-label="Permalink to &quot;1. `generateIdeas(array $scoutedArticles)`&quot;">​</a></h3><p>Takes a list of raw RSS data and prompts Gemini to act as an editorial director. It returns a JSON structure containing 3-5 unique, high-value editorial angles that combine multiple sources into a coherent narrative.</p><h3 id="_2-generatedraft-array-idea" tabindex="-1">2. <code>generateDraft(array $idea)</code> <a class="header-anchor" href="#_2-generatedraft-array-idea" aria-label="Permalink to &quot;2. `generateDraft(array $idea)`&quot;">​</a></h3><p>The heaviest operation. It uses <strong>Blueprint Prompting</strong> to instruct Gemini to write a 1500-2000 word technical deep-dive.</p><ul><li>Demands the output in valid, raw HTML (<code>&lt;h1&gt;</code>, <code>&lt;h2&gt;</code>, <code>&lt;p&gt;</code>, <code>&lt;ul&gt;</code>, <code>&lt;blockquote&gt;</code>).</li><li>Enforces tone guidelines (senior developer, objective, no fluff).</li><li>Injects the <code>current_date</code> to prevent temporal hallucinations.</li></ul><h3 id="_3-translatearticle-string-title-string-summary-string-content-string-targetlocale" tabindex="-1">3. <code>translateArticle(string $title, string $summary, string $content, string $targetLocale)</code> <a class="header-anchor" href="#_3-translatearticle-string-title-string-summary-string-content-string-targetlocale" aria-label="Permalink to &quot;3. `translateArticle(string $title, string $summary, string $content, string $targetLocale)`&quot;">​</a></h3><p>Handles on-demand translation of the <code>title</code>, <code>summary</code>, and <code>content</code>.</p><ul><li>Uses Blueprint Prompting with explicit XML input blocks (<code>&lt;input_title&gt;</code>, <code>&lt;input_summary&gt;</code>, <code>&lt;input_content&gt;</code>) to prevent AI models from echoing example placeholders.</li><li>Enforces strict anti-placeholder validation using <code>Article::isInvalidTranslation()</code> before saving or returning.</li><li>Caches the result in the <code>translations</code> JSON column of the <code>Article</code> model.</li></ul><h2 id="api-integration-fallbacks" tabindex="-1">API Integration &amp; Fallbacks <a class="header-anchor" href="#api-integration-fallbacks" aria-label="Permalink to &quot;API Integration &amp; Fallbacks&quot;">​</a></h2><ul><li><strong>OpenRouter Integration:</strong> Due to rate limits, <code>GeminiService</code> routes traffic through OpenRouter.</li><li><strong>Fallback Chain:</strong> If Gemini 2.0 fails or hits a 429, OpenRouter automatically cascades to secondary models (limited to 3 fallbacks to respect free-tier constraints).</li><li><strong>Timeouts:</strong> API calls have aggressive timeout bounds to prevent PHP worker exhaustion during API degraded states.</li></ul>',13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};